function release_check( $ok, string $message ): void { if ( ! $ok ) { throw new RuntimeException( 'FAIL: ' . $message ); } ++$GLOBALS['release_checks']; WP_CLI::log( 'PASS: ' . $message ); }
function release_reject( callable $fn, string $message ): void { try { $fn(); } catch ( Throwable $e ) { release_check( true, $message ); return; } throw new RuntimeException( 'FAIL: ' . $message ); }
function release_drain(): void { for ( $i=0; $i<200 && Queue::status()['pending']; ++$i ) { $result=Queue::run(1000); if($result['errors']||!$result['processed']){throw new RuntimeException('Queue failed.');} } }
